#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    long long mod = 998244353;
    long long t;
    cin>>t;
    while(t--){
        long long n;
        cin>>n;
        vector<vector<long long>> arr(n+1);
        
        for(int i=1;i<=n;i++){
            long long a;
            cin>>a;
            arr[a].push_back(i);
        }
        
        vector<long long> dp(n+2,0),nx(n+2,0);
        dp[0] = 1;
        
        for(long long x=1;x<=n;x++){
            fill(nx.begin(),nx.end(),0);
            
            for(long long l=0;l<x;l++){
                if(dp[l]==0) continue;
                
                long long rVal = x-1-l;
                long long r = n-rVal;
                
                for(long long s=0;s<2;s++){
                    if(s==1 && x==n) break;
                    
                    long long q = (s==0)?(l+1):r;
                    bool ok = true;
                    
                    for(long long i:arr[x]){
                        bool g = false;
                        if(i>=q && l+max(0LL,i-r)==(i+1)/2-1){
                            g = true;
                        }else if(i<=q && rVal+max(0LL,l-i+1)==(n-i+2)/2-1){
                            g = true;
                        }
                        if(!g){ 
                            ok = false;
                            break;
                        }
                    }
                    
                    if(!ok){
                        continue;
                    }
                    
                    long long k = (s==0)?(l+1):l;
                    nx[k] = (nx[k]+dp[l])%mod;
                }
            }
            swap(dp,nx);
        }
        long long ans = 0;
        for(long long k=0;k<=n;k++){
            ans = (ans+dp[k])%mod;
        }
        
        cout<<ans<<"\n";
    }
}
